window._htmlParts[0] = "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>IB Resume BA — Design System</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Libre+Baskerville:ital,wght@0,400;0,700;1,400&family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=DM+Sans:wght@300;400;500;600;700&family=IBM+Plex+Sans:wght@300;400;500;600&family=Space+Grotesk:wght@400;500;600&family=Inter:wght@300;400;500;600;700&family=DM+Mono:wght@400;500&family=JetBrains+Mono:wght@400;500&family=Source+Code+Pro:wght@400;500&family=Fira+Code:wght@400;500&family=Inconsolata:wght@400;500;700&family=Instrument+Serif:ital@0;1&display=swap" rel="stylesheet">
  <style>
    :root {
      --heading-font: 'Playfair Display', serif;
      --body-font: 'Inter', sans-serif;
      --mono-font: 'DM Mono', monospace;
      --accent-font: 'Inter', sans-serif;
      --accent-gold: #C9A96E;
      --bg-body: #0A0A0A;
      --bg-card: #141312;
      --text-primary: #F5F5F5;
      --text-secondary: #888888;
      --color-green: #2ECC71;
      --color-red: #E74C3C;
      --color-orange: #F39C12;
      --border-radius: 6px;
      --btn-radius: 6px;
      --input-radius: 6px;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      background: var(--bg-body);
      color: var(--text-primary);
      font-family: var(--body-font);
      line-height: 1.6;
    }

    /* TAB NAVIGATION */
    .tab-nav {
      position: sticky;
      top: 0;
      z-index: 100;
      display: flex;
      gap: 1px;
      background: rgba(10, 10, 10, 0.97);
      backdrop-filter: blur(12px);
      padding: 0 8px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
    }

    .tab-nav::-webkit-scrollbar {
      height: 0;
    }

    .tab-btn {
      padding: 12px 18px;
      background: transparent;
      border: none;
      border-bottom: 2px solid transparent;
      color: var(--text-secondary);
      font-family: 'Inter', sans-serif;
      cursor: pointer;
      font-size: 11px;
      font-weight: 600;
      letter-spacing: 0.05em;
      white-space: nowrap;
      transition: all 0.2s ease;
    }

    .tab-btn:hover {
      color: var(--text-primary);
    }

    .tab-btn.active {
      color: var(--text-primary);
      border-bottom-color: var(--accent-gold);
    }

    /* TAB CONTENT */
    .tab-content {
      display: none;
      animation: fadeIn 0.3s ease;
    }

    .tab-content.active {
      display: block;
    }

    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    /* DESIGN COMPARE LAYOUT */
    .dc-split {
      display: grid;
      grid-template-columns: 1fr 400px;
      gap: 40px;
      max-width: 1600px;
      margin: 0 auto;
      padding: 40px;
    }

    .dc-left {
      flex: 1;
    }

    .dc-right {
      position: sticky;
      top: 80px;
      height: max-content;
      background: var(--bg-card);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--border-radius);
      padding: 20px;
    }

    .dc-section {
      margin-bottom: 50px;
    }

    .dc-section-title {
      font-family: var(--heading-font);
      font-size: 18px;
      font-weight: 500;
      color: var(--text-primary);
      margin-bottom: 16px;
      padding-bottom: 12px;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    }

    .dc-section-subtitle {
      font-size: 12px;
      color: var(--text-secondary);
      margin-bottom: 20px;
      display: block;
    }

    .dc-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 12px;
    }

    /* DESIGN CARD */
    .dc-card {
      background: var(--bg-card);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--border-radius);
      padding: 14px;
      cursor: pointer;
      transition: all 0.2s ease;
      position: relative;
    }

    .dc-card:hover {
      border-color: rgba(255, 255, 255, 0.15);
      background: rgba(255, 255, 255, 0.02);
    }

    .dc-card.selected {
      border-color: var(--accent-gold);
      background: rgba(201, 169, 110, 0.08);
    }

    .dc-label {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 10px;
      font-size: 11px;
      font-weight: 600;
      color: var(--text-secondary);
    }

    .dc-label span:first-child {
      flex: 1;
    }

    .dc-tag {
      display: inline-block;
      padding: 2px 6px;
      background: rgba(255, 255, 255, 0.1);
      border-radius: 3px;
      font-size: 9px;
      color: var(--text-secondary);
      margin-left: 8px;
    }

    .dc-tag-cur {
      background: var(--accent-gold);
      color: #111;
    }

    .dc-tag-alt {
      background: rgba(101, 148, 245, 0.2);
      color: #6594F5;
    }

    .dc-preview {
      background: rgba(255, 255, 255, 0.02);
      border: 1px solid rgba(255, 255, 255, 0.06);
      border-radius: var(--border-radius);
      padding: 12px;
      margin-bottom: 10px;
      min-height: 60px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .dc-meta {
      font-size: 10px;
      color: var(--text-secondary);
    }

    .dc-meta code {
      background: rgba(255, 255, 255, 0.08);
      padding: 2px 4px;
      border-radius: 3px;
      font-family: var(--mono-font);
      display: block;
      word-break: break-all;
    }

    /* PAGE CONTENT */
    .page-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 60px 40px;
    }

    .bank-ticker {
      overflow: hidden;
      padding: 12px 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
      margin-bottom: 60px;
    }

    .bank-ticker-text {
      font-family: var(--body-font);
      font-size: 11px;
      font-weight: 500;
      color: var(--text-secondary);
      letter-spacing: 0.2em;
      white-space: nowrap;
    }

    .hero-section {
      display: flex;
      gap: 60px;
      align-items: flex-start;
    }

    .hero-left {
      flex: 1;
    }

    .hero-badge {
      font-size: 11px;
      color: var(--text-secondary);
      letter-spacing: 0.15em;
      margin-bottom: 20px;
    }

    .hero-title {
      font-family: var(--heading-font);
      font-size: 52px;
      font-weight: 400;
      line-height: 1.15;
      color: var(--text-primary);
      margin-bottom: 8px;
    }

    .hero-subtitle {
      font-family: var(--accent-font);
      font-size: 52px;
      font-style: italic;
      color: var(--accent-gold);
      margin-bottom: 30px;
    }

    .hero-description {
      font-family: var(--body-font);
      font-size: 14px;
      color: var(--text-secondary);
      max-width: 400px;
      line-height: 1.7;
    }

    .hero-stats {
      display: flex;
      gap: 40px;
      margin-top: 40px;
    }

    .hero-stat-value {
      font-family: var(--mono-font);
      font-size: 28px;
      color: var(--text-primary);
    }

    .hero-stat-label {
      font-size: 10px;
      color: var(--text-secondary);
      letter-spacing: 0.1em;
      margin-top: 4px;
    }

    .form-card {
      width: 400px;
      background: var(--bg-card);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--border-radius);
      padding: 40px;
    }

    .form-label {
      display: block;
      font-size: 10px;
      color: var(--text-secondary);
      letter-spacing: 0.1em;
      margin-bottom: 6px;
    }

    .form-field {
      background: #1a1a1a;
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: var(--input-radius);
      padding: 12px 14px;
      color: var(--text-secondary);
      font-size: 14px;
      margin-bottom: 16px;
    }

    .form-button {
      background: var(--accent-gold);
      color: #111;
      text-align: center;
      padding: 14px;
      border-radius: var(--btn-radius);
      font-weight: 600;
      font-size: 14px;
      font-family: var(--body-font);
      width: 100%;
      border: none;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .form-button:hover {
      background: rgba(201, 169, 110, 0.9);
    }

    .form-note {
      font-size: 11px;
      color: var(--text-secondary);
      text-align: center;
      margin-top: 16px;
    }

    /* UPLOAD PAGE */
    .upload-section {
      text-align: center;
      max-width: 600px;
      margin: 80px auto;
    }

    .upload-heading {
      font-family: var(--heading-font);
      font-size: 42px;
      color: var(--text-primary);
      margin-bottom: 40px;
    }

    .upload-zone {
      border: 2px dashed rgba(255, 255, 255, 0.2);
      border-radius: var(--border-radius);
      padding: 60px 40px;
      background: rgba(255, 255, 255, 0.02);
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .upload-zone:hover {
      border-color: var(--accent-gold);
      background: rgba(201, 169, 110, 0.05);
    }

    .upload-text {
      font-size: 16px;
      color: var(--text-secondary);
      margin-bottom: 10px;
    }

    .progress-label {
      font-size: 11px;
      color: var(--text-secondary);
      letter-spacing: 0.1em;
      text-transform: uppercase;
      margin-top: 30px;
    }

    /* BANK GRID */
    .bank-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
      gap: 20px;
      margin: 40px 0;
    }

    .bank-card {
      background: var(--bg-card);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--border-radius);
      padding: 24px;
      text-align: center;
      cursor: pointer;
      transition: all 0.2s ease;
    }

    .bank-card:hover {
      border-color: var(--accent-gold);
      background: rgba(201, 169, 110, 0.08);
    }

    .bank-name {
      font-family: var(--heading-font);
      font-size: 16px;
      font-weight: 500;
      color: var(--text-primary);
    }

    /* RESULTS PAGE */
    .results-container {
      max-width: 1400px;
      margin: 0 auto;
      padding: 40px;
      display: grid;
      grid-template-columns: 1fr 350px;
      gap: 40px;
    }

    .results-main {
      flex: 1;
    }

    .results-sidebar {
      position: sticky;
      top: 100px;
      height: max-content;
    }

    .score-circle {
      width: 140px;
      height: 140px;
      border-radius: 50%;
      background: conic-gradient(var(--color-green) 95%, rgba(255, 255, 255, 0.1) 0);
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      position: relative;
    }

    .score-circle-inner {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      background: var(--bg-body);
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
    }

    .score-number {
      font-family: var(--mono-font);
      font-size: 32px;
      font-weight: 600;
      color: var(--text-primary);
    }

    .score-label {
      font-size: 10px;
      color: var(--text-secondary);
      letter-spacing: 0.05em;
    }

    .results-heading {
      font-family: var(--heading-font);
      font-size: 28px;
      color: var(--text-primary);
      margin: 30px 0 20px;
    }

    .category-bar {
      background: var(--bg-card);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--border-radius);
      padding: 16px;
      margin-bottom: 12px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .category-name {
      font-size: 12px;
      font-weight: 600;
      color: var(--text-primary);
    }

    .category-progress {
      flex: 1;
      height: 6px;
      background: rgba(255, 255, 255, 0.1);
      border-radius: 3px;
      margin: 0 16px;
      overflow: hidden;
    }

    .category-progress-fill {
      height: 100%;
      background: var(--color-green);
      border-radius: 3px;
    }

    .category-score {
      font-family: var(--mono-font);
      font-size: 11px;
      color: var(--text-secondary);
      min-width: 40px;
      text-align: right;
    }

    .issue-card {
      background: var(--bg-card);
      border: 2px solid var(--color-red);
      border-left-width: 6px;
      border-radius: var(--border-radius);
      padding: 20px;
      margin-bottom: 16px;
    }

    .issue-badge {
      display: inline-block;
      background: var(--color-red);
      color: white;
      padding: 4px 8px;
      border-radius: 3px;
      font-size: 10px;
      font-weight: 600;
      margin-bottom: 8px;
    }

    .issue-title {
      font-size: 14px;
      font-weight: 600;
      color: var(--text-primary);
      margin-bottom: 8px;
    }

    .issue-description {
      font-size: 12px;
      color: var(--text-secondary);
      margin-bottom: 16px;
      line-height: 1.6;
    }

    .issue-before-after {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 12px;
      padding-top: 16px;
      border-top: 1px solid rgba(255, 255, 255, 0.06);
    }

    .before-after-item {
      font-size: 11px;
    }

    .before-after-label {
      display: block;
      color: var(--text-secondary);
      margin-bottom: 6px;
      font-weight: 600;
    }

    .before-text {
      background: rgba(231, 76, 60, 0.1);
      padding: 8px;
      border-left: 2px solid var(--color-red);
      border-radius: 3px;
      color: var(--text-secondary);
      line-height: 1.5;
    }

    .after-text {
      background: rgba(46, 204, 113, 0.1);
      padding: 8px;
      border-left: 2px solid var(--color-green);
      border-radius: 3px;
      color: var(--text-primary);
      line-height: 1.5;
    }

    .sidebar-card {
      background: var(--bg-card);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: var(--border-radius);
      padding: 16px;
      margin-bottom: 16px;
    }

    .sidebar-card-title {
      font-size: 11px;
      font-weight: 600;
      color: var(--text-secondary);
      letter-spacing: 0.05em;
      margin-bottom: 12px;
      text-transform: uppercase;
    }

    .sidebar-item {
      display: flex;
      justify-content: space-between;
      padding: 8px 0;
      border-bottom: 1px solid rgba(255, 255, 255, 0.06);
      font-size: 12px;
    }

    .sidebar-item:last-child {
      border-bottom: none;
    }

    .sidebar-item-label {
      color: var(--text-secondary);
    }

    .sidebar-item-value {
      color: var(--text-primary);
