function selectCard(card) {
  var section = card.closest('.dc-section');
  if (section) {
    section.querySelectorAll('.dc-card').forEach(function(c) {
      c.classList.remove('selected');
    });
  }
  card.classList.add('selected');

  var varName = card.getAttribute('data-var');
  var varValue = card.getAttribute('data-val');
  if (varName && varValue && varName !== 'visual-only') {
    updateRootVar('--' + varName, varValue);
    var ctrl = document.getElementById('ctrl-' + varName);
    if (ctrl) {
      for (var i = 0; i < ctrl.options.length; i++) {
        if (ctrl.options[i].value === varValue) {
          ctrl.value = varValue;
          break;
        }
      }
    }
  }
}

input.new_string:
function selectCard(card) {
  var section = card.closest('.dc-section');
  if (section) {
    // Remove selected from all cards in section
    section.querySelectorAll('.dc-card').forEach(function(c) {
      c.classList.remove('selected');
      // Move "Current" tag: remove from all cards in this section
      var tag = c.querySelector('.dc-tag-cur');
      if (tag) {
        tag.classList.remove('dc-tag-cur');
        tag.classList.add('dc-tag-alt');
        tag.textContent = 'Alt';
      }
    });
  }
  card.classList.add('selected');

  // Add "Current" tag to the newly selected card
  var cardTag = card.querySelector('.dc-tag');
  if (cardTag) {
    cardTag.classList.remove('dc-tag-alt');
    cardTag.classList.add('dc-tag-cur');
    cardTag.textContent = 'Current';
  }

  var varName = card.getAttribute('data-var');
  var varValue = card.getAttribute('data-val');
  if (varName && varValue && varName !== 'visual-only') {
    updateRootVar('--' + varName, varValue);
    // Sync with control panel dropdown
    var ctrl = document.getElementById('ctrl-' + varName);
    if (ctrl) {
      for (var i = 0; i < ctrl.options.length; i++) {
        if (ctrl.options[i].value === varValue) {
          ctrl.value = varValue;
          break;
        }
      }
    }
  }
}

